import java.util.*;

public class Main {
    int maxProfit(int[] prices) {
        int best = 0;
        int n = prices.length;
        for (int i = 0; i < n; i++) {                             // every possible buy day
            for (int j = i + 1; j < n; j++) {                       // every possible later sell day
                int profit = prices[j] - prices[i];
                best = Math.max(best, profit);                          // keep the best profit seen so far
            }
        }
        return best;
    }

    public static void main(String[] args) {
        int[] prices = {7, 1, 5, 3, 6, 4};
        Main solution = new Main();
        System.out.println(solution.maxProfit(prices));
    }
}

